mapper.select:
SELECT item.id, item.student_id, item.goal_id, goal.goal_type, goal.category_code, category.label AS category_label, goal.goal_text, item.initial_level, item.current_level, item.phase, item.status FROM student_training_goal item JOIN training_goal goal ON goal.id = item.goal_id JOIN training_goal_category category ON category.code = goal.category_code WHERE item.student_id = #{studentId}
AND goal.goal_text LIKE CONCAT('%', #{keyword}, '%')
AND goal.category_code = #{categoryCode}
AND item.status = #{status}
ORDER BY category.display_order, item.id

SELECT id, category_code, goal_text, goal_type, owner_student_id
FROM training_goal
WHERE id = #{id}

SELECT COUNT(*) > 0
FROM student_training_goal
WHERE student_id = #{studentId} AND goal_id = #{goalId}

mapper.update:
UPDATE student_training_goal
SET current_level = #{currentLevel}, phase = #{phase}, status = #{status}
WHERE id = #{id} AND student_id = #{studentId}
